        "everyday|4:1|3|p0": "ナッツアレルギーがあるので、このカレーの材料を確認していただけますか。",
        "everyday|4:1|3|p1": "私たちは全員ベジタリアンなので、卵が入っていないか必ず確かめてください。",
        "everyday|4:1|3|p2": "辛さを控えめにしていただけますか。息子は唐辛子があまり得意ではないんです。",
        "everyday|4:1|3|p3": "ここは量がとても多いので、残りを持ち帰り用に包んでいただけますか。",
        "everyday|4:1|3|p4": "お会計にもうサービス料が含まれているので、チップを置く必要はありません。",
        "everyday|4:1|4|title": "ウドゥピでの誕生日ディナー",
        "everyday|4:1|4|text": "おばあさんの80歳の誕生日に、キランはウドゥピの人気レストランに席を予約しました。ウェイターはメニューを持ってきて、前菜にパニールティッカをすすめました。キランのいとこのニシャはピーナッツアレルギーがあるので、キランはすべての料理を念入りに確認してほしいとウェイターに頼みました。おばあさんはメイン料理の辛さを控えめにしてほしいと言い、料理人は快く応じてくれました。デザートには、家族みんなで大きなガドバドアイスクリームを分けて食べました。お会計のとき、キランは5パーセントのサービス料がすでに含まれていることに気づきました。それでも、ウェイターがとても辛抱強く対応してくれたので、少しチップを置きました。残ったロティは持ち帰りにして家に持って帰りました。",
        "everyday|4:1|4|q0": "キランはなぜウェイターにすべての料理を確認するよう頼みましたか。",
        "everyday|4:1|4|q0o0": "いとこにピーナッツアレルギーがあるから",
        "everyday|4:1|4|q0o1": "おばあさんがベジタリアンだから",
        "everyday|4:1|4|q0o2": "料理が冷めていたから",
        "everyday|4:1|4|q0o3": "メニューに値段がなかったから",
        "everyday|4:1|4|q1": "家族はデザートに何を分けて食べましたか。",
