        "everyday|4:1|4|q1o3": "フルーツサラダ",
        "everyday|4:1|4|q2": "キランはなぜそれでもチップを置きましたか。",
        "everyday|4:1|4|q2o0": "ウェイターがとても辛抱強かったから",
