        "everyday|4:1|5|title": "夕食の注文",
        "everyday|4:1|5|scenario": "アナニャと友達がプネーのレストランにいます。ウェイターのマノージが注文を取りに来ます。",
        "everyday|4:1|5|l0": "こんばんは。ご注文はお決まりですか。それとも、もう少しお時間が必要ですか。",
        "everyday|4:1|5|l1": "決まったと思います。今日のおすすめは何ですか。",
        "everyday|4:1|5|l2": "本日はマルヴァニ風フィッシュカレーと、ベジタリアン・ターリーがございます。",
        "everyday|4:1|5|l3": "友達にターリーを一つお願いします。フィッシュカレーはとても辛いですか。",
        "everyday|4:1|5|l4": "かなり辛いですが、よろしければシェフが辛さを控えめにできます。",
        "everyday|4:1|5|l5": "はい、控えめにしてください。それと、友達にナッツアレルギーがあるので、ターリーにカシューナッツは入れないでください。",
        "everyday|4:1|5|l6": "かしこまりました、厨房に伝えます。お飲み物はいかがですか。",
        "everyday|4:1|5|l7": "甘いラッシーを二つお願いします。それと、最後にUPIで払えますか。",
        "everyday|4:1|5|l8": "はい、UPIもカードもご利用いただけます。すぐにお飲み物をお持ちします。",
        "everyday|4:1|5|l9": "ありがとうございます、ご親切に。",
        "everyday|4:1|5|q0": "今日のおすすめは何ですか。",
