        "everyday|5:1|1|p0": "3月5日から2泊で予約をお願いしたいのですが。",
        "everyday|5:1|1|p1": "今週末、ダブルルームの空き状況を確認していただけますか。",
        "everyday|5:1|1|p2": "チェックインは正午ですが、それより前でもお荷物をお預かりできます。",
        "everyday|5:1|1|p3": "チェックアウトを遅くしてもらうことはできますか。電車が6時発なんです。",
        "everyday|5:1|1|p4": "タクシーの運転手さんがロビーでお待ちです。",
