        "everyday|5:1|3|p0": "新しいタオルを2枚と、枕をもう一つ部屋に届けていただけますか。",
        "everyday|5:1|3|p1": "申し訳ないのですが、204号室のエアコンがまったく動きません。",
        "everyday|5:1|3|p2": "もう3時なのに、客室清掃がまだ部屋を掃除してくれていません。",
        "everyday|5:1|3|p3": "苦情を言いたいわけではないのですが、部屋がとてもうるさいんです。",
        "everyday|5:1|3|p4": "11時以降もルームサービスは使えますか。それとも、その時間には厨房が閉まっていますか。",
        "everyday|5:1|4|title": "マディケーリのうるさい夜",
        "everyday|5:1|4|text": "ニキルと妻のシュレヤは、連休にマディケーリの小さなホテルを予約しました。チェックインのとき、受付の人は1階のダブルルームを用意してくれました。その夜、エアコンがガタガタと大きな音を立て、部屋は暑くて眠れませんでした。ニキルはフロントに電話して、丁寧に苦情を伝えました。支配人は謝って、丘が見える上の階の静かな部屋に移してくれました。翌朝、頼んでもいないのに、客室清掃の人が新しいタオルと枕を多めに持ってきてくれました。チェックアウトのとき、支配人はおわびとして無料の朝食を出してくれました。",
        "everyday|5:1|4|q0": "最初の部屋の何が問題でしたか。",
