        "everyday|5:1|5|title": "チェックイン",
        "everyday|5:1|5|scenario": "ラーフルは夕方フッバッリのホテルに着き、フロントのファラーがチェックインの手続きをします。",
        "everyday|5:1|5|l0": "こんばんは、ホテル・サンガムへようこそ。ご予約はいただいていますか。",
        "everyday|5:1|5|l1": "はい、ラーフル・ジョーシーの名前で3泊です。",
        "everyday|5:1|5|l2": "はい、確認できました。金曜日までダブルルームですね。写真付きの身分証明書を拝見できますか。",
        "everyday|5:1|5|l3": "アーダールカードです。料金に朝食は含まれていますか。",
        "everyday|5:1|5|l4": "はい、含まれています。朝食は7時から10時までレストランでお召し上がりいただけます。",
        "everyday|5:1|5|l5": "よかった。できればエレベーターから離れた部屋にしていただけますか。眠りが浅いもので。",
        "everyday|5:1|5|l6": "かしこまりました。廊下の奥の静かな312号室をご用意します。",
        "everyday|5:1|5|l7": "ありがとうございます。それと、金曜日のチェックアウトは何時ですか。",
        "everyday|5:1|5|l8": "チェックアウトは11時ですが、もう少しお時間が必要でしたらお知らせください。",
        "everyday|5:1|5|l9": "とても助かります。どうもありがとう。",
