        "everyday|6:1|3|p3": "今のアナウンス、聞こえましたか。荷物を5番ホームまで運ばないといけません。",
        "everyday|6:1|3|p4": "時刻表によると、マイスール行きの最終バスは10時に出ます。",
        "everyday|6:1|4|title": "ぎりぎり間に合った",
        "everyday|6:1|4|text": "アーシャは姉の結婚式のために、フッバッリからプネーへ向かうところでした。2か月前に座席予約をしていて、S4車両の下段の寝台を取っていました。駅で、3時間の遅れが出ているとアナウンスがありました。アーシャはスマホでバスの時刻表を調べ、もっと早くプネーに着くバスを見つけました。電車の切符をオンラインでキャンセルすると、払い戻しは2日で口座に戻ってきました。ポーターが少しの料金で重い荷物をバス乗り場まで運んでくれました。アーシャはメヘンディの儀式にぎりぎり間に合いました。",
        "everyday|6:1|4|q0": "アーシャはなぜプネーへ行くところでしたか。",
