        "everyday|6:1|5|title": "運休になった電車",
        "everyday|6:1|5|scenario": "マイスール駅で、カヴィタはベンガルール行きの電車が運休になったことを知り、問い合わせ窓口のスレーシュに助けを求めます。",
        "everyday|6:1|5|l0": "すみません、今チャームンディ・エクスプレスが運休だというアナウンスを聞いたんですが、本当ですか。",
        "everyday|6:1|5|l1": "残念ながらそうなんです。マンディヤ付近の線路に問題がありまして。",
        "everyday|6:1|5|l2": "どうしよう。2時にベンガルールで大事な会議があるんです。ほかに方法はありますか。",
        "everyday|6:1|5|l3": "3番ホームから11時15分発の急行があります。普段は1時半までに着きます。",
        "everyday|6:1|5|l4": "まだ席は残っていますか。",
        "everyday|6:1|5|l5": "あいにく自由席の車両だけです。指定席はすべてキャンセル待ちです。",
        "everyday|6:1|5|l6": "自由席で大丈夫です。それと、運休になった切符はどうなりますか。",
        "everyday|6:1|5|l7": "鉄道側が運休にしたので、1週間以内に全額払い戻されます。",
        "everyday|6:1|5|l8": "払い戻しのために用紙に記入する必要はありますか。",
        "everyday|6:1|5|l9": "いいえ、オンラインで予約されたので自動的に払い戻されます。お気をつけて。",
        "everyday|6:1|5|q0": "チャームンディ・エクスプレスはなぜ運休になりましたか。",
